-- M5 PRODUCTION (project bonxyxluzlxfkdetryoo): normalize stored legacy-CDN media URLs to the default pull zone.
-- GENERATED by scripts/m5-cdn/build-sql.mjs from Phase 0 __PHASE0__. Do not edit by hand; regenerate.
-- Rule: exact origin substitution 'https://cdn.dongphugia.com.vn/' -> 'https://dpg-products.b-cdn.net/'. Path bytes, case
-- and percent-encoding are unchanged; nothing outside that exact origin is touched. Column fields: anchored at the start of
-- the value. HTML (products.description, product_descriptions.clean_html) and JSON (products.specs): only occurrences that
-- directly follow a quote, and only if afterwards no old-origin occurrence remains (Phase 0: 100% quote-anchored).
-- Excluded (stay on the old origin, still rendered by display normalization): URLs whose object is not in the storage
-- zone (list below, from Phase 0), every Blog field (the Public legacy-Blog rule only recognises old-origin files), and
-- HTML/JSON rows that already contain the new origin (their rollback would be ambiguous).
-- Ledger dpg_control.m5_cdn_ledger keeps (table, pk, column, md5 before, md5 after) for an exact, conditional rollback
-- (003_cdn_normalization_rollback.sql). Concurrency: rows are locked and updated only if still equal to the value read in
-- the same statement; products.version + 1 once per touched product (open Admin editors get VERSION_CONFLICT and reload).
-- updated_at is left unchanged (URL hygiene, not a content edit). Idempotent: a re-run only touches remaining old URLs.
-- BATCH __BATCH__ of __BATCHES__ (product ids >= __LO__ and < __HI__). Measured: one transaction over all rows grows the database by
-- ~124 MB (dead row versions, TOAST, indexes) and exceeds the 350 MiB free-tier hard stop, so the work is split into batches.
-- Run the batches IN ORDER, each as its own SQL Editor run, waiting ~2 minutes between runs (autovacuum, tuned by batch 1, reuses
-- the space). After the last batch run once: VACUUM (ANALYZE) on the five tables (optional, see the report).
begin;
set local lock_timeout = '5s';
set local statement_timeout = '10min';
do $$ begin
  if not exists (select 1 from dpg_control.target_contract where project_name = 'dongphugia-runtime' and production_writes_allowed)
     or (select count(*) from dpg_app.products) < 17000 then
    raise exception 'M5_CDN_GUARD_FAILED: not the Production project';
  end if;
  if pg_database_size(current_database()) > __MAX_START_BYTES__ then
    raise exception 'M5_CDN_GUARD_FAILED: database larger than the rehearsed headroom allows; stop and review';
  end if;
end $$;

__PROLOGUE__
create table if not exists dpg_control.m5_cdn_ledger (
  tbl text not null, pk integer not null, col text not null,
  old_md5 uuid not null, new_md5 uuid not null, product_id integer,
  migrated_at timestamptz not null default now(), rolled_back_at timestamptz,
  primary key (tbl, pk, col));
alter table dpg_control.m5_cdn_ledger enable row level security;
revoke all on dpg_control.m5_cdn_ledger from public;

create temp table m5_cdn_excluded (url text primary key) on commit drop;
insert into m5_cdn_excluded (url) select unnest(array[
-- excluded:begin
__EXCLUDED__
-- excluded:end
]::text[]);

create function pg_temp.m5_col(v text) returns text language sql immutable as
  $f$ select regexp_replace(v, '^https://cdn\.dongphugia\.com\.vn/', 'https://dpg-products.b-cdn.net/') $f$;
create function pg_temp.m5_doc(v text) returns text language sql immutable as
  $f$ select replace(replace(v, '"https://cdn.dongphugia.com.vn/', '"https://dpg-products.b-cdn.net/'),
                     '''https://cdn.dongphugia.com.vn/', '''https://dpg-products.b-cdn.net/') $f$;
create function pg_temp.m5_col_ok(v text) returns boolean language sql stable as
  $f$ select starts_with(v, 'https://cdn.dongphugia.com.vn/') and not exists (select 1 from m5_cdn_excluded e where e.url = v) $f$;
create function pg_temp.m5_doc_ok(v text) returns boolean language sql stable as
  $f$ select position('https://cdn.dongphugia.com.vn/' in v) > 0
        and position('https://dpg-products.b-cdn.net/' in v) = 0
        and position('https://cdn.dongphugia.com.vn/' in pg_temp.m5_doc(v)) = 0
        and not exists (select 1 from m5_cdn_excluded e where position(e.url || '"' in v) > 0 or position(e.url || '''' in v) > 0) $f$;

-- 1. Gallery images.
with c as (select t.id, t.product_id, t.image_url as old_v from dpg_app.product_images t where t.product_id >= __LO__ and t.product_id < __HI__ and pg_temp.m5_col_ok(t.image_url) for update),
u as (update dpg_app.product_images t set image_url = pg_temp.m5_col(c.old_v) from c where t.id = c.id and t.image_url = c.old_v
      returning t.id, t.product_id, c.old_v, t.image_url as new_v)
insert into dpg_control.m5_cdn_ledger (tbl, pk, col, old_md5, new_md5, product_id)
select 'product_images', id, 'image_url', md5(old_v)::uuid, md5(new_v)::uuid, product_id from u
on conflict (tbl, pk, col) do update set old_md5 = excluded.old_md5, new_md5 = excluded.new_md5, migrated_at = now(), rolled_back_at = null;

-- 2. Product documents.
with c as (select t.id, t.product_id, t.url as old_v from dpg_app.product_documents t where t.product_id >= __LO__ and t.product_id < __HI__ and pg_temp.m5_col_ok(t.url) for update),
u as (update dpg_app.product_documents t set url = pg_temp.m5_col(c.old_v) from c where t.id = c.id and t.url = c.old_v
      returning t.id, t.product_id, c.old_v, t.url as new_v)
insert into dpg_control.m5_cdn_ledger (tbl, pk, col, old_md5, new_md5, product_id)
select 'product_documents', id, 'url', md5(old_v)::uuid, md5(new_v)::uuid, product_id from u
on conflict (tbl, pk, col) do update set old_md5 = excluded.old_md5, new_md5 = excluded.new_md5, migrated_at = now(), rolled_back_at = null;

-- 3. Description HTML used by the Public product page.
with c as (select t.id, t.product_id, t.clean_html as old_v from dpg_app.product_descriptions t where t.product_id >= __LO__ and t.product_id < __HI__ and pg_temp.m5_doc_ok(t.clean_html) for update),
u as (update dpg_app.product_descriptions t set clean_html = pg_temp.m5_doc(c.old_v) from c where t.id = c.id and t.clean_html = c.old_v
      returning t.id, t.product_id, c.old_v, t.clean_html as new_v)
insert into dpg_control.m5_cdn_ledger (tbl, pk, col, old_md5, new_md5, product_id)
select 'product_descriptions', id, 'clean_html', md5(old_v)::uuid, md5(new_v)::uuid, product_id from u
on conflict (tbl, pk, col) do update set old_md5 = excluded.old_md5, new_md5 = excluded.new_md5, migrated_at = now(), rolled_back_at = null;

-- 4. Products: main image, Admin description HTML, specs JSON; version + 1 once per changed product.
with c as (
  select p.id, p.version, p.image_main_url, p.description, p.specs from dpg_app.products p
  where p.id >= __LO__ and p.id < __HI__ and (pg_temp.m5_col_ok(p.image_main_url) or pg_temp.m5_doc_ok(p.description) or pg_temp.m5_doc_ok(p.specs::text)) for update),
n as (
  select c.*,
    case when pg_temp.m5_col_ok(c.image_main_url) then pg_temp.m5_col(c.image_main_url) else c.image_main_url end as img2,
    case when pg_temp.m5_doc_ok(c.description) then pg_temp.m5_doc(c.description) else c.description end as desc2,
    case when pg_temp.m5_doc_ok(c.specs::text) then pg_temp.m5_doc(c.specs::text)::jsonb else c.specs end as specs2
  from c),
u as (
  update dpg_app.products p set image_main_url = n.img2, description = n.desc2, specs = n.specs2, version = p.version + 1
  from n where p.id = n.id and p.version = n.version
  returning p.id, n.image_main_url as o1, n.img2 as n1, n.description as o2, n.desc2 as n2, n.specs::text as o3, n.specs2::text as n3)
insert into dpg_control.m5_cdn_ledger (tbl, pk, col, old_md5, new_md5, product_id)
select 'products', u.id, v.col, md5(v.o)::uuid, md5(v.nw)::uuid, u.id
from u, lateral (values ('image_main_url', u.o1, u.n1), ('description', u.o2, u.n2), ('specs', u.o3, u.n3)) v(col, o, nw)
where v.o is distinct from v.nw
on conflict (tbl, pk, col) do update set old_md5 = excluded.old_md5, new_md5 = excluded.new_md5, migrated_at = now(), rolled_back_at = null;

-- 5. Products whose only change was in a child row: version + 1 so an open Admin editor reloads.
update dpg_app.products p set version = p.version + 1
where p.id >= __LO__ and p.id < __HI__ and p.id in (select product_id from dpg_control.m5_cdn_ledger where migrated_at = now() and tbl <> 'products')
  and p.id not in (select pk from dpg_control.m5_cdn_ledger where migrated_at = now() and tbl = 'products');

-- Result (expected values are in the Phase 0 / rehearsal report).
select 'migrated' as kind, tbl || '.' || col as field, count(*) as n from dpg_control.m5_cdn_ledger where migrated_at = now() group by 2
union all select 'remaining_old_origin', 'product_images.image_url', count(*) from dpg_app.product_images where starts_with(image_url, 'https://cdn.dongphugia.com.vn/')
union all select 'remaining_old_origin', 'products.image_main_url', count(*) from dpg_app.products where starts_with(image_main_url, 'https://cdn.dongphugia.com.vn/')
union all select 'remaining_old_origin', 'product_documents.url', count(*) from dpg_app.product_documents where starts_with(url, 'https://cdn.dongphugia.com.vn/')
union all select 'remaining_old_origin', 'product_descriptions.clean_html', count(*) from dpg_app.product_descriptions where position('https://cdn.dongphugia.com.vn/' in clean_html) > 0
union all select 'remaining_old_origin', 'products.description', count(*) from dpg_app.products where position('https://cdn.dongphugia.com.vn/' in description) > 0
union all select 'remaining_old_origin', 'products.specs', count(*) from dpg_app.products where position('https://cdn.dongphugia.com.vn/' in specs::text) > 0
union all select 'database_bytes', 'after', pg_database_size(current_database())
order by 1, 2;
__EPILOGUE__
commit;
